+/// rustfmt splits after `ui` still counts.
+fn joined_code(src: &str) -> String {
+    let mut out = String::new();
+    for line in src.lines().map(str::trim).filter(|line| !line.starts_with("//")) {
+        if !line.starts_with('.') {
+            out.push('\n');
+        }
+        out.push_str(line);
+    }
